#include <errno.h>
#include <limits.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

struct bigint {
    uint32_t *digits;
    size_t length;
    size_t capacity;
};

static void reserve(struct bigint *value, size_t capacity)
{
    if (capacity > value->capacity) {
        uint32_t *digits = realloc(value->digits, capacity * sizeof(*digits));
        if (digits == NULL) {
            fputs("memory allocation failed\n", stderr);
            exit(EXIT_FAILURE);
        }
        value->digits = digits;
        value->capacity = capacity;
    }
}

static struct bigint add(const struct bigint *left, const struct bigint *right)
{
    struct bigint result = {0};
    size_t length = left->length > right->length ? left->length : right->length;
    uint64_t carry = 0;

    reserve(&result, length + 1);
    for (size_t i = 0; i < length || carry != 0; ++i) {
        uint64_t sum = carry;
        if (i < left->length) {
            sum += left->digits[i];
        }
        if (i < right->length) {
            sum += right->digits[i];
        }
        result.digits[i] = (uint32_t)(sum % 1000000000U);
        carry = sum / 1000000000U;
        result.length = i + 1;
    }
    return result;
}

static void print_bigint(const struct bigint *value)
{
    printf("%u", value->digits[value->length - 1]);
    for (size_t i = value->length - 1; i-- > 0;) {
        printf("%09u", value->digits[i]);
    }
    putchar('\n');
}

int main(int argc, char **argv)
{
    char *end;
    unsigned long long n;
    struct bigint previous = {(uint32_t[]){0}, 1, 1};
    struct bigint current = {(uint32_t[]){1}, 1, 1};

    if (argc != 2 || argv[1][0] == '-') {
        fprintf(stderr, "usage: %s N\n", argv[0]);
        return EXIT_FAILURE;
    }
    errno = 0;
    n = strtoull(argv[1], &end, 10);
    if (errno == ERANGE || *end != '\0') {
        fprintf(stderr, "invalid N: %s\n", argv[1]);
        return EXIT_FAILURE;
    }

    for (unsigned long long i = 0; i < n; ++i) {
        struct bigint next = add(&previous, &current);
        free(previous.digits);
        previous = current;
        current = next;
    }
    print_bigint(&previous);
    free(previous.digits);
    free(current.digits);
    return EXIT_SUCCESS;
}

